import { describe, it, expect, vi } from 'vitest';
import { RateLimiter } from '../../../../src/mcp/security/rate-limiter.js';

describe('client bucket reset', () => {
  it('resets every endpoint bucket owned by the exact client and retains other clients', () => {
    vi.useFakeTimers();
    const limiter = new RateLimiter({ tokensPerSecond: 1, maxBurst: 1 });
    limiter.addEndpointLimit({ pattern: '^/one', tokensPerSecond: 1, maxBurst: 1 });
    limiter.addEndpointLimit({ pattern: '^/two', tokensPerSecond: 1, maxBurst: 1 });
    try {
      for (const client of ['client', 'client:ep0', 'client:other', 'other']) {
        for (const endpoint of ['/one', '/two', '/ordinary']) expect(limiter.check(client, endpoint).allowed).toBe(true);
      }
      limiter.resetClient('client');
      for (const endpoint of ['/one', '/two', '/ordinary']) {
        expect(limiter.check('client', endpoint).allowed).toBe(true);
        expect(limiter.check('client:other', endpoint).allowed).toBe(false);
        expect(limiter.check('client:ep0', endpoint).allowed).toBe(false);
        expect(limiter.check('other', endpoint).allowed).toBe(false);
      }
    } finally { limiter.dispose(); vi.useRealTimers(); }
  });
});

import { describe, it, expect, vi } from 'vitest';
import { RateLimiter } from '../../../../src/mcp/security/rate-limiter.js';

describe('token cost validation', () => {
  it.each([-1, Number.NaN, Number.POSITIVE_INFINITY, Number.NEGATIVE_INFINITY])('rejects invalid cost %s before mutating a bucket', cost => {
    vi.useFakeTimers();
    const limiter = new RateLimiter({ tokensPerSecond: 1, maxBurst: 2 });
    try {
      expect(() => limiter.consume('client', undefined, cost)).toThrow(RangeError);
      expect(limiter.getClientStats('client')).toBeNull();
      expect(limiter.getStats().totalRequests).toBe(0);
      expect(limiter.consume('client', undefined, 2).allowed).toBe(true);
      expect(limiter.check('client').allowed).toBe(false);
    } finally { limiter.dispose(); vi.useRealTimers(); }
  });
  it('preserves zero and fractional nonnegative costs', () => {
    const limiter = new RateLimiter({ tokensPerSecond: 1, maxBurst: 2 });
    try {
      expect(limiter.consume('client', undefined, 0).allowed).toBe(true);
      expect(limiter.consume('client', undefined, 0.5).allowed).toBe(true);
    } finally { limiter.dispose(); }
  });
});

import { describe, it, expect, vi } from 'vitest';
import { RateLimiter } from '../../../../src/mcp/security/rate-limiter.js';

describe('stateful endpoint regular expressions', () => {
  it.each(['g', 'y'])('uses the same policy and bucket on repeated checks with %s', flags => {
    vi.useFakeTimers();
    const limiter = new RateLimiter({ tokensPerSecond: 10, maxBurst: 20 });
    const pattern = new RegExp('^/expensive', flags);
    pattern.lastIndex = 4;
    limiter.addEndpointLimit({ pattern, tokensPerSecond: 1, maxBurst: 2 });
    try {
      expect(limiter.check('client', '/expensive').headers['X-RateLimit-Limit']).toBe(2);
      expect(limiter.check('client', '/expensive').allowed).toBe(true);
      expect(limiter.check('client', '/expensive').allowed).toBe(false);
      expect(limiter.check('other', '/ordinary').headers['X-RateLimit-Limit']).toBe(20);
      expect(pattern.lastIndex).toBe(4);
    } finally { limiter.dispose(); vi.useRealTimers(); }
  });
});

/**
 * Issue #905: RateLimiter.wait() must never hang when the requested cost can
 * never be admitted (tokens > maxBurst, or a bucket that never refills).
 * Uses real timers so a hang shows up as a real timeout, not a mocked clock.
 */
import { describe, it, expect, afterEach, vi } from 'vitest';
import { RateLimiter } from '../../../../src/mcp/security/rate-limiter.js';

const SETTLE_BUDGET_MS = 250;

type Outcome = { status: 'resolved' | 'rejected' | 'timeout'; value?: unknown; elapsed: number };

/** Report how `p` settled, or 'timeout' if it did not settle within `ms`. */
async function settleWithin<T>(p: Promise<T>, ms: number): Promise<Outcome> {
  const start = Date.now();
  let timer: ReturnType<typeof setTimeout> | undefined;
  const timeout = new Promise<{ status: 'timeout' }>(resolve => {
    timer = setTimeout(() => resolve({ status: 'timeout' }), ms);
  });
  try {
    const outcome = await Promise.race([
      p.then(
        v => ({ status: 'resolved' as const, value: v as unknown }),
        e => ({ status: 'rejected' as const, value: e as unknown }),
      ),
      timeout,
    ]);
    return { ...outcome, elapsed: Date.now() - start };
  } finally {
    clearTimeout(timer);
  }
}

describe('RateLimiter.wait() over-burst (#905)', () => {
  let limiter: RateLimiter | undefined;
  afterEach(() => { limiter?.dispose(); limiter = undefined; });

  it('rejects promptly with RangeError when tokens > default maxBurst', async () => {
    limiter = new RateLimiter({ tokensPerSecond: 1000, maxBurst: 5 });
    const r = await settleWithin(limiter.wait('client', undefined, 6), SETTLE_BUDGET_MS);
    expect(r.status).toBe('rejected');
    expect(r.value).toBeInstanceOf(RangeError);
    expect((r.value as Error).message).toMatch(/exceeds maxBurst 5/);
    expect(r.elapsed).toBeLessThan(SETTLE_BUDGET_MS);
    // The rejected call neither created nor drained a bucket.
    expect(limiter.getClientStats('client')).toBeNull();
    expect(limiter.getStats().totalRequests).toBe(0);
  });

  it('uses the endpoint-specific maxBurst of the resolved bucket', async () => {
    limiter = new RateLimiter({ tokensPerSecond: 1000, maxBurst: 100 });
    limiter.addEndpointLimit({ pattern: /^tight$/, tokensPerSecond: 1000, maxBurst: 3 });
    const r = await settleWithin(limiter.wait('client', 'tight', 4), SETTLE_BUDGET_MS);
    expect(r.status).toBe('rejected');
    expect(r.value).toBeInstanceOf(RangeError);
    // The same cost against the default bucket is admissible.
    const ok = await settleWithin(limiter.wait('client', 'other', 4), SETTLE_BUDGET_MS);
    expect(ok.status).toBe('resolved');
    expect((ok.value as { allowed: boolean }).allowed).toBe(true);
  });

  it('rejects instead of spinning when an exhausted bucket can never refill', async () => {
    limiter = new RateLimiter({ tokensPerSecond: 1000, maxBurst: 100 });
    limiter.addEndpointLimit({ pattern: /^frozen$/, tokensPerSecond: 0, maxBurst: 1 });
    expect(limiter.consume('client', 'frozen').allowed).toBe(true);
    const r = await settleWithin(limiter.wait('client', 'frozen', 1), SETTLE_BUDGET_MS);
    expect(r.status).toBe('rejected');
    expect(r.value).toBeInstanceOf(RangeError);
  });

  it('still waits for refill and resolves when tokens === maxBurst', async () => {
    limiter = new RateLimiter({ tokensPerSecond: 100, maxBurst: 2 });
    expect(limiter.consume('client', undefined, 2).allowed).toBe(true);
    const r = await settleWithin(limiter.wait('client', undefined, 2), 1000);
    expect(r.status).toBe('resolved');
    expect((r.value as { allowed: boolean }).allowed).toBe(true);
    expect(r.elapsed).toBeGreaterThanOrEqual(10); // genuinely waited for refill
  });

  it('rejects after sleeping if an endpoint limit lowers maxBurst below the cost', async () => {
    limiter = new RateLimiter({ tokensPerSecond: 50, maxBurst: 5 });
    expect(limiter.consume('client', 'x', 5).allowed).toBe(true);
    const pending = limiter.wait('client', 'x', 3); // must sleep ~60ms for refill
    limiter.addEndpointLimit({ pattern: /^x$/, tokensPerSecond: 50, maxBurst: 2 });
    const r = await settleWithin(pending, 1000);
    expect(r.status).toBe('rejected');
    expect((r.value as Error).message).toMatch(/exceeds maxBurst 2/);
  });

  it('rejects instead of spinning when retryAfter exceeds the setTimeout maximum', async () => {
    // 1 token per 10^7 s: retryAfter is ~1e10 ms, which setTimeout would clamp to 1 ms.
    limiter = new RateLimiter({ tokensPerSecond: 1000, maxBurst: 100 });
    limiter.addEndpointLimit({ pattern: /^slow$/, tokensPerSecond: 1e-7, maxBurst: 1 });
    expect(limiter.consume('client', 'slow').allowed).toBe(true);
    const warnings: string[] = [];
    const onWarning = (w: Error) => { warnings.push(w.name); };
    process.on('warning', onWarning);
    try {
      const r = await settleWithin(limiter.wait('client', 'slow', 1), SETTLE_BUDGET_MS);
      expect(r.status).toBe('rejected');
      expect(r.value).toBeInstanceOf(RangeError);
      expect((r.value as Error).message).toMatch(/2147483647/);
      expect(r.elapsed).toBeLessThan(SETTLE_BUDGET_MS);
      await new Promise(resolve => setTimeout(resolve, 20));
      expect(warnings).not.toContain('TimeoutOverflowWarning');
    } finally {
      process.off('warning', onWarning);
    }
  });

  it('does not drain a new bucket when the clock ticks between reading now and creating it', () => {
    limiter = new RateLimiter({ tokensPerSecond: 1000, maxBurst: 1 });
    // consume() reads `now` (t) before getBucket() stamps the new bucket (t + 1).
    const t = Date.now();
    const clock = vi.spyOn(Date, 'now').mockReturnValueOnce(t).mockReturnValue(t + 1);
    try {
      expect(limiter.consume('client').allowed).toBe(true);
    } finally {
      clock.mockRestore();
    }
  });

  it('keeps rejecting invalid costs with RangeError', async () => {
    limiter = new RateLimiter({ tokensPerSecond: 10, maxBurst: 5 });
    await expect(limiter.wait('client', undefined, Number.NaN)).rejects.toBeInstanceOf(RangeError);
  });
});

/**
 * Agentic QE v3 - Rate Limiter Tests
 * Tests for token bucket rate limiting
 */

import { describe, it, expect, beforeEach, afterEach, vi } from 'vitest';
import {
  RateLimiter,
  SlidingWindowRateLimiter,
  createRateLimiter,
  createStrictRateLimiter,
  createSlidingWindowLimiter,
} from '../../../../src/mcp/security/rate-limiter';

describe('RateLimiter', () => {
  let limiter: RateLimiter;

  beforeEach(() => {
    vi.useFakeTimers();
    limiter = createRateLimiter({
      tokensPerSecond: 10,
      maxBurst: 20,
      perClient: true,
    });
  });

  afterEach(() => {
    limiter.dispose();
    vi.useRealTimers();
  });

  describe('basic rate limiting', () => {
    it('should allow requests within limit', () => {
      const result = limiter.check('client1');

      expect(result.allowed).toBe(true);
      expect(result.remaining).toBeLessThanOrEqual(20);
    });

    it('should track remaining tokens', () => {
      // Use some tokens
      limiter.check('client1');
      limiter.check('client1');
      limiter.check('client1');

      const result = limiter.check('client1');
      expect(result.remaining).toBe(16); // 20 - 4 = 16
    });

    it('should deny requests when tokens exhausted', () => {
      // Exhaust all tokens
      for (let i = 0; i < 20; i++) {
        limiter.check('client1');
      }

      const result = limiter.check('client1');
      expect(result.allowed).toBe(false);
      expect(result.remaining).toBe(0);
      expect(result.retryAfter).toBeDefined();
    });

    it('should provide retry-after time', () => {
      // Exhaust tokens
      for (let i = 0; i < 20; i++) {
        limiter.check('client1');
      }

      const result = limiter.check('client1');
      expect(result.retryAfter).toBeGreaterThan(0);
      expect(result.retryAfter).toBeLessThanOrEqual(1000); // Max 1 second wait for 10 tokens/sec
    });
  });

  describe('per-client limiting', () => {
    it('should maintain separate buckets per client', () => {
      // Exhaust client1's tokens
      for (let i = 0; i < 20; i++) {
        limiter.check('client1');
      }

      // client2 should still have tokens
      const result = limiter.check('client2');
      expect(result.allowed).toBe(true);
      expect(result.remaining).toBe(19);
    });

    it('should use global bucket when no client specified', () => {
      // Create limiter without per-client limiting
      const globalLimiter = createRateLimiter({
        tokensPerSecond: 10,
        maxBurst: 20,
        perClient: false,
      });

      const result1 = globalLimiter.check();
      const result2 = globalLimiter.check();

      expect(result1.remaining - result2.remaining).toBe(1);

      globalLimiter.dispose();
    });
  });

  describe('token refill', () => {
    it('should refill tokens over time', async () => {
      // Use some tokens
      for (let i = 0; i < 10; i++) {
        limiter.check('client1');
      }

      const beforeRefill = limiter.check('client1');
      expect(beforeRefill.remaining).toBe(9);

      // Wait for tokens to refill (100ms = 1 token at 10/sec)
      vi.advanceTimersByTime(1000);

      const afterRefill = limiter.check('client1');
      expect(afterRefill.remaining).toBeGreaterThan(9);

    });

    it('should not exceed max burst', async () => {
      // Wait a long time - should still cap at maxBurst
      vi.advanceTimersByTime(10000);

      const result = limiter.check('client1');
      expect(result.remaining).toBe(19); // maxBurst - 1
      expect(result.remaining).toBeLessThanOrEqual(20);

    });
  });

  describe('consume multiple tokens', () => {
    it('should consume multiple tokens at once', () => {
      const result = limiter.consume('client1', undefined, 5);

      expect(result.allowed).toBe(true);
      expect(result.remaining).toBe(15);
    });

    it('should deny if not enough tokens', () => {
      const result = limiter.consume('client1', undefined, 25);

      expect(result.allowed).toBe(false);
    });
  });

  describe('async wait', () => {
    it('should wait for tokens to become available', async () => {
      // Exhaust tokens
      for (let i = 0; i < 20; i++) {
        limiter.check('client1');
      }

      const waitPromise = limiter.wait('client1');

      // Advance time to allow token refill
      vi.advanceTimersByTime(200);

      const result = await waitPromise;
      expect(result.allowed).toBe(true);

    });
  });

  describe('endpoint-specific limits', () => {
    it('should apply endpoint-specific limits', () => {
      limiter.addEndpointLimit({
        pattern: /\/api\/admin/,
        tokensPerSecond: 5,
        maxBurst: 10,
      });

      const adminResult = limiter.check('client1', '/api/admin/users');
      // Token bucket may have slight timing variations, use range check
      expect(adminResult.remaining).toBeGreaterThanOrEqual(8); // ~10 maxBurst - 1 (±1 for timing)
      expect(adminResult.remaining).toBeLessThanOrEqual(10);

      // Normal endpoint has separate bucket from admin endpoint
      const normalResult = limiter.check('client1', '/api/users');
      expect(normalResult.remaining).toBeGreaterThanOrEqual(18); // ~20 maxBurst - 1 (±1 for timing)
      expect(normalResult.remaining).toBeLessThanOrEqual(20);
    });

    it('should clear endpoint limits', () => {
      limiter.addEndpointLimit({
        pattern: '/test',
        tokensPerSecond: 1,
        maxBurst: 2,
      });

      limiter.clearEndpointLimits();

      const result = limiter.check('client1', '/test');
      expect(result.remaining).toBe(19); // Uses default maxBurst
    });
  });

  describe('reset', () => {
    it('should reset client bucket', () => {
      // Use tokens
      for (let i = 0; i < 10; i++) {
        limiter.check('client1');
      }

      limiter.resetClient('client1');

      const result = limiter.check('client1');
      expect(result.remaining).toBe(19); // Full bucket
    });

    it('should reset all buckets', () => {
      limiter.check('client1');
      limiter.check('client2');
      limiter.check('client3');

      limiter.reset();

      const stats = limiter.getStats();
      expect(stats.activeBuckets).toBe(1); // Only global bucket
      expect(stats.totalRequests).toBe(0);
    });
  });

  describe('statistics', () => {
    it('should track request statistics', () => {
      limiter.check('client1');
      limiter.check('client2');
      limiter.check('client1');

      const stats = limiter.getStats();

      expect(stats.totalRequests).toBe(3);
      expect(stats.allowedRequests).toBe(3);
      expect(stats.deniedRequests).toBe(0);
    });

    it('should track denied requests', () => {
      // Exhaust tokens
      for (let i = 0; i < 20; i++) {
        limiter.check('client1');
      }

      // Try more requests
      limiter.check('client1');
      limiter.check('client1');

      const stats = limiter.getStats();
      expect(stats.deniedRequests).toBe(2);
    });

    it('should track active buckets', () => {
      limiter.check('client1');
      limiter.check('client2');
      limiter.check('client3');

      const stats = limiter.getStats();
      expect(stats.activeBuckets).toBe(4); // 3 clients + 1 global
    });

    it('should get client-specific stats', () => {
      limiter.check('client1');
      limiter.check('client1');
      limiter.check('client1');

      const clientStats = limiter.getClientStats('client1');

      expect(clientStats).not.toBeNull();
      expect(clientStats?.totalRequests).toBe(3);
    });

    it('should return null for unknown client', () => {
      const stats = limiter.getClientStats('unknown');
      expect(stats).toBeNull();
    });
  });

  describe('rate limit headers', () => {
    it('should provide rate limit headers', () => {
      const result = limiter.check('client1');

      expect(result.headers['X-RateLimit-Limit']).toBe(20);
      expect(result.headers['X-RateLimit-Remaining']).toBe(19);
      expect(result.headers['X-RateLimit-Reset']).toBeDefined();
    });

    it('should include Retry-After when denied', () => {
      // Exhaust tokens
      for (let i = 0; i < 20; i++) {
        limiter.check('client1');
      }

      const result = limiter.check('client1');
      expect(result.headers['Retry-After']).toBeDefined();
      expect(result.headers['Retry-After']).toBeGreaterThan(0);
    });
  });
});

describe('SlidingWindowRateLimiter', () => {
  let limiter: SlidingWindowRateLimiter;

  beforeEach(() => {
    limiter = createSlidingWindowLimiter(1000, 10); // 10 requests per second
  });

  afterEach(() => {
    limiter.dispose();
  });

  describe('basic functionality', () => {
    it('should allow requests within limit', () => {
      const result = limiter.check('client1');

      expect(result.allowed).toBe(true);
      expect(result.remaining).toBe(9);
    });

    it('should deny requests exceeding limit', () => {
      // Make 10 requests
      for (let i = 0; i < 10; i++) {
        limiter.check('client1');
      }

      const result = limiter.check('client1');
      expect(result.allowed).toBe(false);
      expect(result.remaining).toBe(0);
    });

    it('should track per-client limits', () => {
      // Use client1's quota
      for (let i = 0; i < 10; i++) {
        limiter.check('client1');
      }

      // client2 should still have quota
      const result = limiter.check('client2');
      expect(result.allowed).toBe(true);
    });
  });

  describe('sliding window behavior', () => {
    it('should allow requests after window slides', async () => {
      vi.useFakeTimers();

      // Use all quota
      for (let i = 0; i < 10; i++) {
        limiter.check('client1');
      }

      // Wait for window to slide
      vi.advanceTimersByTime(1100);

      const result = limiter.check('client1');
      expect(result.allowed).toBe(true);

      vi.useRealTimers();
    });
  });

  describe('reset', () => {
    it('should reset specific client', () => {
      for (let i = 0; i < 5; i++) {
        limiter.check('client1');
      }

      limiter.reset('client1');

      const result = limiter.check('client1');
      expect(result.remaining).toBe(9);
    });

    it('should reset all clients', () => {
      limiter.check('client1');
      limiter.check('client2');

      limiter.reset();

      const result1 = limiter.check('client1');
      const result2 = limiter.check('client2');

      expect(result1.remaining).toBe(9);
      expect(result2.remaining).toBe(9);
    });
  });
});

describe('createStrictRateLimiter', () => {
  it('should create limiter with strict defaults', () => {
    const limiter = createStrictRateLimiter();

    // Should have lower limits (10 req/s, 20 burst)
    const stats = limiter.getStats();
    expect(stats.activeBuckets).toBe(1);

    // Exhaust 20 tokens
    for (let i = 0; i < 20; i++) {
      limiter.check('client1');
    }

    const result = limiter.check('client1');
    expect(result.allowed).toBe(false);

    limiter.dispose();
  });
});

/**
 * Agentic QE v3 - Validation Orchestrator Unit Tests
 * Comprehensive tests for the ValidationOrchestrator and individual validators
 */

import { describe, it, expect, beforeEach, afterEach} from 'vitest';
import {
  ValidationOrchestrator,
  getOrchestrator,
  createOrchestrator,
} from '../../../../../src/mcp/security/validators/validation-orchestrator';
import {
  PathTraversalValidator,
  PATH_TRAVERSAL_PATTERNS,
  DANGEROUS_PATH_COMPONENTS,
} from '../../../../../src/mcp/security/validators/path-traversal-validator';
import {
  RegexSafetyValidator,
  REDOS_PATTERNS,
  countQuantifierNesting,
  hasExponentialBacktracking,
} from '../../../../../src/mcp/security/validators/regex-safety-validator';
import {
  CommandValidator,
  DEFAULT_ALLOWED_COMMANDS,
  BLOCKED_COMMAND_PATTERNS,
} from '../../../../../src/mcp/security/validators/command-validator';
import type {
  IValidationStrategy,
  ValidationResult,
  RiskLevel,
  PathValidationResult,
  CommandValidationResult,
} from '../../../../../src/mcp/security/validators/interfaces';

// =============================================================================
// Test Helpers
// =============================================================================

/**
 * Create a mock validation strategy for testing
 */
function createMockStrategy(
  name: string,
  validateFn: (input: unknown) => ValidationResult,
  riskLevel: RiskLevel = 'medium'
): IValidationStrategy {
  return {
    name,
    validate: validateFn,
    getRiskLevel: () => riskLevel,
  };
}

// =============================================================================
// ValidationOrchestrator Tests
// =============================================================================

describe('ValidationOrchestrator', () => {
  describe('Constructor', () => {
    it('should create orchestrator with default strategies when registerDefaults is true', () => {
      const orchestrator = new ValidationOrchestrator(true);
      const names = orchestrator.getStrategyNames();

      expect(names).toContain('path-traversal');
      expect(names).toContain('regex-safety');
      expect(names).toContain('command-injection');
      expect(names.length).toBe(3);
    });

    it('should create empty orchestrator when registerDefaults is false', () => {
      const orchestrator = new ValidationOrchestrator(false);
      const names = orchestrator.getStrategyNames();

      expect(names.length).toBe(0);
    });

    it('should create orchestrator with default strategies by default (no argument)', () => {
      const orchestrator = new ValidationOrchestrator();
      const names = orchestrator.getStrategyNames();

      expect(names.length).toBe(3);
    });
  });

  describe('registerStrategy', () => {
    let orchestrator: ValidationOrchestrator;

    beforeEach(() => {
      orchestrator = new ValidationOrchestrator(false);
    });

    afterEach(() => {
      // Reset state to prevent leaks between tests
    });

    it('should register a custom strategy', () => {
      const strategy = createMockStrategy('custom', () => ({
        valid: true,
        riskLevel: 'none',
      }));

      orchestrator.registerStrategy(strategy);

      expect(orchestrator.getStrategyNames()).toContain('custom');
    });

    it('should overwrite existing strategy with same name', () => {
      const strategy1 = createMockStrategy('test', () => ({
        valid: true,
        riskLevel: 'none',
      }));
      const strategy2 = createMockStrategy('test', () => ({
        valid: false,
        error: 'always fails',
        riskLevel: 'high',
      }));

      orchestrator.registerStrategy(strategy1);
      orchestrator.registerStrategy(strategy2);

      const result = orchestrator.validateWith<ValidationResult>('test', 'input');
      expect(result.valid).toBe(false);
      expect(result.error).toBe('always fails');
    });

    it('should allow registering multiple strategies', () => {
      orchestrator.registerStrategy(createMockStrategy('a', () => ({ valid: true, riskLevel: 'none' })));
      orchestrator.registerStrategy(createMockStrategy('b', () => ({ valid: true, riskLevel: 'none' })));
      orchestrator.registerStrategy(createMockStrategy('c', () => ({ valid: true, riskLevel: 'none' })));

      expect(orchestrator.getStrategyNames().length).toBe(3);
    });
  });

  describe('getStrategy', () => {
    let orchestrator: ValidationOrchestrator;

    beforeEach(() => {
      orchestrator = new ValidationOrchestrator(true);
    });

    it('should return registered strategy by name', () => {
      const strategy = orchestrator.getStrategy('path-traversal');

      expect(strategy).toBeDefined();
      expect(strategy?.name).toBe('path-traversal');
    });

    it('should return undefined for non-existent strategy', () => {
      const strategy = orchestrator.getStrategy('non-existent');

      expect(strategy).toBeUndefined();
    });
  });

  describe('getStrategyNames', () => {
    it('should return all registered strategy names', () => {
      const orchestrator = new ValidationOrchestrator(true);
      const names = orchestrator.getStrategyNames();

      expect(Array.isArray(names)).toBe(true);
      expect(names).toContain('path-traversal');
      expect(names).toContain('regex-safety');
      expect(names).toContain('command-injection');
    });

    it('should return empty array when no strategies registered', () => {
      const orchestrator = new ValidationOrchestrator(false);
      const names = orchestrator.getStrategyNames();

      expect(names).toEqual([]);
    });
  });

  describe('validateWith', () => {
    let orchestrator: ValidationOrchestrator;

    beforeEach(() => {
      orchestrator = new ValidationOrchestrator(true);
    });

    it('should validate using specific strategy', () => {
      const result = orchestrator.validateWith<PathValidationResult>(
        'path-traversal',
        'safe/path/file.txt'
      );

      expect(result.valid).toBe(true);
      expect(result.riskLevel).toBe('none');
    });

    it('should throw error for non-existent strategy', () => {
      expect(() => {
        orchestrator.validateWith('non-existent', 'input');
      }).toThrow("Strategy 'non-existent' not found");
    });

    it('should pass options to the strategy', () => {
      const result = orchestrator.validateWith<PathValidationResult>(
        'path-traversal',
        '/absolute/path',
        { allowAbsolute: true }
      );

      expect(result.valid).toBe(true);
    });

    it('should return typed results', () => {
      const result = orchestrator.validateWith<CommandValidationResult>(
        'command-injection',
        'ls -la'
      );

      expect(result).toHaveProperty('blockedPatterns');
      expect(result).toHaveProperty('sanitizedCommand');
    });
  });

  describe('validateAll', () => {
    let orchestrator: ValidationOrchestrator;

    beforeEach(() => {
      orchestrator = new ValidationOrchestrator(true);
    });

    it('should return results from all validators', () => {
      const results = orchestrator.validateAll('test-input');

      expect(results.size).toBe(3);
      expect(results.has('path-traversal')).toBe(true);
      expect(results.has('regex-safety')).toBe(true);
      expect(results.has('command-injection')).toBe(true);
    });

    it('should return map of validation results', () => {
      const results = orchestrator.validateAll('safe-input');

      for (const [_, result] of results) {
        expect(result).toHaveProperty('valid');
        expect(result).toHaveProperty('riskLevel');
      }
    });

    it('should handle validation errors gracefully', () => {
      const failingStrategy = createMockStrategy('failing', () => {
        throw new Error('Validation failed');
      });

      orchestrator.registerStrategy(failingStrategy);
      const results = orchestrator.validateAll('input');

      const failingResult = results.get('failing');
      expect(failingResult?.valid).toBe(false);
      expect(failingResult?.error).toBe('Validation failed');
      expect(failingResult?.riskLevel).toBe('high');
    });

    it('should handle unknown error types gracefully', () => {
      const throwingStrategy: IValidationStrategy = {
        name: 'throwing',
        validate: () => {
          throw 'string error'; // Non-Error throw
        },
        getRiskLevel: () => 'medium',
      };

      orchestrator.registerStrategy(throwingStrategy);
      const results = orchestrator.validateAll('input');

      const result = results.get('throwing');
      expect(result?.valid).toBe(false);
      expect(result?.error).toBe('Unknown error');
    });
  });

  describe('hasIssues', () => {
    let orchestrator: ValidationOrchestrator;

    beforeEach(() => {
      orchestrator = new ValidationOrchestrator(false);
    });

    it('should return false when all results are valid', () => {
      const results = new Map<string, ValidationResult>([
        ['test1', { valid: true, riskLevel: 'none' }],
        ['test2', { valid: true, riskLevel: 'none' }],
      ]);

      expect(orchestrator.hasIssues(results)).toBe(false);
    });

    it('should return true when any result is invalid', () => {
      const results = new Map<string, ValidationResult>([
        ['test1', { valid: true, riskLevel: 'none' }],
        ['test2', { valid: false, error: 'Failed', riskLevel: 'high' }],
      ]);

      expect(orchestrator.hasIssues(results)).toBe(true);
    });

    it('should return false for empty results', () => {
      const results = new Map<string, ValidationResult>();

      expect(orchestrator.hasIssues(results)).toBe(false);
    });

    it('should return true when all results are invalid', () => {
      const results = new Map<string, ValidationResult>([
        ['test1', { valid: false, error: 'Error 1', riskLevel: 'high' }],
        ['test2', { valid: false, error: 'Error 2', riskLevel: 'critical' }],
      ]);

      expect(orchestrator.hasIssues(results)).toBe(true);
    });
  });

  describe('getHighestRisk', () => {
    let orchestrator: ValidationOrchestrator;

    beforeEach(() => {
      orchestrator = new ValidationOrchestrator(false);
    });

    it('should return "none" for empty results', () => {
      const results = new Map<string, ValidationResult>();

      expect(orchestrator.getHighestRisk(results)).toBe('none');
    });

    it('should return "none" when all results have no risk', () => {
      const results = new Map<string, ValidationResult>([
        ['test1', { valid: true, riskLevel: 'none' }],
        ['test2', { valid: true, riskLevel: 'none' }],
      ]);

      expect(orchestrator.getHighestRisk(results)).toBe('none');
    });

    it('should return highest risk level from results', () => {
      const results = new Map<string, ValidationResult>([
        ['test1', { valid: false, riskLevel: 'low' }],
        ['test2', { valid: false, riskLevel: 'critical' }],
        ['test3', { valid: false, riskLevel: 'medium' }],
      ]);

      expect(orchestrator.getHighestRisk(results)).toBe('critical');
    });

    it('should correctly order all risk levels', () => {
      const levels: RiskLevel[] = ['none', 'low', 'medium', 'high', 'critical'];

      for (let i = 0; i < levels.length; i++) {
        const results = new Map<string, ValidationResult>([
          ['test', { valid: i > 0 ? false : true, riskLevel: levels[i] }],
        ]);
        expect(orchestrator.getHighestRisk(results)).toBe(levels[i]);
      }
    });

    it('should return "high" when high is the maximum', () => {
      const results = new Map<string, ValidationResult>([
        ['test1', { valid: false, riskLevel: 'low' }],
        ['test2', { valid: false, riskLevel: 'high' }],
        ['test3', { valid: false, riskLevel: 'medium' }],
      ]);

      expect(orchestrator.getHighestRisk(results)).toBe('high');
    });
  });

  describe('getAllIssues', () => {
    let orchestrator: ValidationOrchestrator;

    beforeEach(() => {
      orchestrator = new ValidationOrchestrator(false);
    });

    it('should return empty array when no issues', () => {
      const results = new Map<string, ValidationResult>([
        ['test1', { valid: true, riskLevel: 'none' }],
        ['test2', { valid: true, riskLevel: 'none' }],
      ]);

      const issues = orchestrator.getAllIssues(results);

      expect(issues).toEqual([]);
    });

    it('should extract all issues from invalid results', () => {
      const results = new Map<string, ValidationResult>([
        ['test1', { valid: false, error: 'Error 1', riskLevel: 'high' }],
        ['test2', { valid: true, riskLevel: 'none' }],
        ['test3', { valid: false, error: 'Error 3', riskLevel: 'critical' }],
      ]);

      const issues = orchestrator.getAllIssues(results);

      expect(issues.length).toBe(2);
      expect(issues).toContainEqual({
        validator: 'test1',
        error: 'Error 1',
        riskLevel: 'high',
      });
      expect(issues).toContainEqual({
        validator: 'test3',
        error: 'Error 3',
        riskLevel: 'critical',
      });
    });

    it('should skip invalid results without error messages', () => {
      const results = new Map<string, ValidationResult>([
        ['test1', { valid: false, riskLevel: 'high' }], // No error
        ['test2', { valid: false, error: 'Has error', riskLevel: 'medium' }],
      ]);

      const issues = orchestrator.getAllIssues(results);

      expect(issues.length).toBe(1);
      expect(issues[0].validator).toBe('test2');
    });

    it('should preserve validator names in issues', () => {
      const results = new Map<string, ValidationResult>([
        ['path-traversal', { valid: false, error: 'Path error', riskLevel: 'critical' }],
        ['command-injection', { valid: false, error: 'Command error', riskLevel: 'high' }],
      ]);

      const issues = orchestrator.getAllIssues(results);

      const validators = issues.map((i) => i.validator);
      expect(validators).toContain('path-traversal');
      expect(validators).toContain('command-injection');
    });
  });
});

