    it('should fallback on LLM call failure', async () => {
      const failingCaller: LLMCompactCaller = {
        call: vi.fn().mockRejectedValue(new Error('API rate limit')),
      };

      const tier3 = new Tier3LLMCompact({ llmCall: failingCaller });
      const messages: ConversationMessage[] = [
        makeMsg('user', 'Do something'),
      ];

      const result = await tier3.compact(messages);
      expect(result.usedFallback).toBe(true);
      expect(result.summary).toContain('Extractive Fallback');
    });
  });

  describe('token savings', () => {
    it('should report positive savings for non-trivial input', async () => {
      const tier3 = new Tier3LLMCompact();
      const messages: ConversationMessage[] = [];
      for (let i = 0; i < 20; i++) {
        messages.push(makeMsg('user', `Request ${i}: ${'x'.repeat(200)}`));
        messages.push(makeMsg('assistant', `Response ${i}: ${'y'.repeat(200)}`));
      }

      const result = await tier3.compact(messages);
      expect(result.originalMessageCount).toBe(40);
      expect(result.tokensSaved).toBeGreaterThan(0);
    });
  });

  describe('summary truncation', () => {
    it('should truncate oversized LLM response', async () => {
      const verboseCaller: LLMCompactCaller = {
        call: vi.fn().mockResolvedValue('x'.repeat(200_000)), // way over budget
      };

      const tier3 = new Tier3LLMCompact({ llmCall: verboseCaller, maxSummaryTokens: 1_000 });
      const messages: ConversationMessage[] = [makeMsg('user', 'test')];

      const result = await tier3.compact(messages);
      // 1000 tokens * 3 chars = 3000 char limit
      expect(result.summary.length).toBeLessThan(4000);
      expect(result.summary).toContain('[LLM summary truncated');
    });
  });
});

/**
 * Browser Engine Installer (Vibium) — unit tests
 *
 * TDD London school: we inject a spawner so tests never touch PATH, the
 * network, or global npm. The spawner is a simple function that returns
 * canned `SpawnSyncReturns` objects.
 */

import { describe, it, expect } from 'vitest';
import type { SpawnSyncReturns } from 'node:child_process';

import {
  installBrowserEngine,
  detectBrowserEngine,
  detectVibium,
  diagnosePlatform,
  DEFAULT_VIBIUM_SPEC,
  type Spawner,
  type PlatformProbe,
} from '../../../src/init/browser-engine-installer.js';

function makePlatformProbe(overrides: Partial<PlatformProbe>): PlatformProbe {
  return {
    platform: () => 'linux' as NodeJS.Platform,
    arch: () => 'x64',
    existsSync: () => false,
    ...overrides,
  };
}

type MockCall = { bin: string; args: string[] };

function canned(overrides: Partial<SpawnSyncReturns<string>>): SpawnSyncReturns<string> {
  return {
    pid: 1,
    status: 0,
    signal: null,
    stdout: '',
    stderr: '',
    output: [],
    ...overrides,
  } as SpawnSyncReturns<string>;
}

function enoent(): SpawnSyncReturns<string> {
  return canned({
    status: null,
    error: Object.assign(new Error('ENOENT'), { code: 'ENOENT' }),
  });
}

function makeSpawner(
  responses: (call: MockCall, index: number) => SpawnSyncReturns<string>
): { spawner: Spawner; calls: MockCall[] } {
  const calls: MockCall[] = [];
  const spawner: Spawner = (bin, args) => {
    const call: MockCall = { bin, args };
    calls.push(call);
    return responses(call, calls.length - 1);
  };
  return { spawner, calls };
}

describe('browser-engine-installer', () => {
  describe('detectBrowserEngine', () => {
    it('should_reportReady_when_cliAndBrowserPayloadAreUsable', () => {
      const { spawner, calls } = makeSpawner((call) => {
        if (call.args[0] === '--version') return canned({ stdout: 'v26.8.21\n' });
        if (call.args[0] === 'is-installed') return canned({ stdout: 'installed\n' });
        throw new Error(`unexpected call: ${call.bin} ${call.args.join(' ')}`);
      });

      const result = detectBrowserEngine(spawner);

      expect(result).toEqual({ status: 'ready', version: '26.8.21' });
      expect(calls).toEqual([
        { bin: 'vibium', args: ['--version'] },
        { bin: 'vibium', args: ['is-installed'] },
      ]);
    });

    it.each(['26.3.18', '26.8.20', '27.0.0', '26.8.21-rc.1', 'unknown'])('rejects unsupported version %s without claiming readiness', (version) => {
      const { spawner, calls } = makeSpawner(() => canned({ stdout: version }));
      expect(detectBrowserEngine(spawner).status).toBe('unsupported-version');
      expect(calls).toHaveLength(1);
    });

    it('should_reportCliMissing_when_versionProbeCannotStart', () => {
      const { spawner, calls } = makeSpawner(() => enoent());

      const result = detectBrowserEngine(spawner);

      expect(result.status).toBe('cli-missing');
      expect(calls).toEqual([{ bin: 'vibium', args: ['--version'] }]);
    });

    it('should_reportPayloadMissing_when_cliExistsWithoutBrowserPair', () => {
      const { spawner, calls } = makeSpawner((call) =>
        call.args[0] === '--version'
          ? canned({ stdout: 'v26.8.21\n' })
          : canned({ status: 1, stderr: 'Chrome and chromedriver revision mismatch' })
      );

      const result = detectBrowserEngine(spawner);

      expect(result).toEqual({
        status: 'payload-missing',
        version: '26.8.21',
        message: 'Chrome and chromedriver revision mismatch',
      });
      expect(calls.every((call) => call.bin === 'vibium')).toBe(true);
    });
  });

  describe('detectVibium', () => {
    it('extracts semver from stdout v-prefixed output', () => {
      const { spawner, calls } = makeSpawner(() => canned({ stdout: 'v26.3.18\n' }));
      const result = detectVibium(spawner);
      expect(result).toBe('26.3.18');
      expect(calls).toEqual([{ bin: 'vibium', args: ['--version'] }]);
    });

    it('returns null when vibium is not installed', () => {
      const { spawner } = makeSpawner(() => enoent());
      expect(detectVibium(spawner)).toBeNull();
    });

    it('returns "unknown" when vibium exits 0 with empty stdout AND empty stderr', () => {
      const { spawner } = makeSpawner(() => canned({ stdout: '   \n', stderr: '' }));
      expect(detectVibium(spawner)).toBe('unknown');
    });

    // H1 regression — devil's-advocate finding:
    // Many Go CLIs (including some Vibium versions) write --version output to
    // stderr. detectVibium used to read only stdout and silently report 'unknown'.
    describe('H1 regression: stderr fallback', () => {
      it('reads version from stderr when stdout is empty', () => {
        const { spawner } = makeSpawner(() => canned({ stdout: '', stderr: 'v26.3.18\n' }));
        expect(detectVibium(spawner)).toBe('26.3.18');
      });

      it('prefers stdout over stderr when both have content', () => {
        const { spawner } = makeSpawner(() =>
          canned({ stdout: 'v26.3.18\n', stderr: '26.0.0\n' })
        );
        expect(detectVibium(spawner)).toBe('26.3.18');
      });

      it('extracts semver from verbose output like "vibium version 26.3.18"', () => {
        const { spawner } = makeSpawner(() => canned({ stdout: 'vibium version 26.3.18 (linux/amd64)\n' }));
        expect(detectVibium(spawner)).toBe('26.3.18');
      });

      it('handles semver with prerelease tag', () => {
        const { spawner } = makeSpawner(() => canned({ stdout: 'v27.0.0-rc.1\n' }));
        expect(detectVibium(spawner)).toBe('27.0.0-rc.1');
      });

      it('falls back to first whitespace token when no semver match', () => {
        const { spawner } = makeSpawner(() => canned({ stdout: 'unknown-build foo\n' }));
        expect(detectVibium(spawner)).toBe('unknown-build');
      });
    });
  });

  describe('installBrowserEngine', () => {
    it('returns skipped when options.skip is true', () => {
      const result = installBrowserEngine({ skip: true });
      expect(result.status).toBe('skipped');
      // Default spec is version-pinned so `npm install -g` won't silently
      // upgrade past the Vibium release we've verified against.
      expect(result.packageSpec).toBe(DEFAULT_VIBIUM_SPEC);
      expect(DEFAULT_VIBIUM_SPEC).toMatch(/^vibium@/);
    });

    it('returns already-installed when vibium and its browser payload are ready', () => {
      const { spawner, calls } = makeSpawner((call) =>
        call.args[0] === '--version'
          ? canned({ stdout: 'v26.8.21\n' })
          : canned({ stdout: 'installed\n' })
      );
      const result = installBrowserEngine({ spawner });
      expect(result.status).toBe('already-installed');
      // H1 fix: detectVibium now extracts the bare semver, dropping the v prefix.
      expect(result.version).toBe('26.8.21');
      expect(calls).toEqual([
        { bin: 'vibium', args: ['--version'] },
        { bin: 'vibium', args: ['is-installed'] },
      ]);
    });

    it('returns npm-unavailable when npm is missing', () => {
      const { spawner, calls } = makeSpawner((call) => {
        if (call.bin === 'vibium') return enoent();
        if (call.bin === 'npm') return enoent();
        throw new Error(`unexpected bin: ${call.bin}`);
      });
      const result = installBrowserEngine({ spawner });
      expect(result.status).toBe('npm-unavailable');
      expect(result.message).toMatch(/npm is not available/i);
      // vibium check + npm check, no install attempt
      expect(calls).toHaveLength(2);
    });

    it('installs via npm when vibium is missing but npm works', () => {
      let installed = false;
      const { spawner, calls } = makeSpawner((call) => {
        if (call.bin === 'vibium' && call.args[0] === '--version') {
          return installed ? canned({ stdout: 'v26.8.21' }) : enoent();
        }
        if (call.bin === 'vibium' && call.args[0] === 'is-installed') {
          return canned({ stdout: 'installed' });
        }
        if (call.bin === 'npm' && call.args[0] === '--version') {
          return canned({ stdout: '10.2.0' });
        }
        if (call.bin === 'npm' && call.args[0] === 'install') {
          installed = true;
          return canned({ stdout: 'added 1 package' });
        }
        throw new Error(`unexpected call: ${call.bin} ${call.args.join(' ')}`);
      });

      const result = installBrowserEngine({ spawner });
      expect(result.status).toBe('installed');
      // H1 fix: detectVibium now extracts the bare semver.
      expect(result.version).toBe('26.8.21');
      // version check, npm check, npm install, version + payload verification
      expect(calls).toHaveLength(5);
      expect(calls[2]).toEqual({ bin: 'npm', args: ['install', '-g', DEFAULT_VIBIUM_SPEC] });
    });

    it('should_reinstall_when_cliExistsButBrowserPayloadIsMissing', () => {
      let payloadChecks = 0;
      const { spawner, calls } = makeSpawner((call) => {
        if (call.bin === 'vibium' && call.args[0] === '--version') {
          return canned({ stdout: 'v26.8.21' });
        }
        if (call.bin === 'vibium' && call.args[0] === 'is-installed') {
          payloadChecks += 1;
          return payloadChecks === 1
            ? canned({ status: 1, stderr: 'browser assets missing' })
            : canned({ stdout: 'installed' });
        }
        if (call.bin === 'npm' && call.args[0] === '--version') return canned({ stdout: '10.2.0' });
        if (call.bin === 'npm' && call.args[0] === 'install') return canned({ stdout: 'added 1 package' });
        throw new Error(`unexpected call: ${call.bin} ${call.args.join(' ')}`);
      });

      const result = installBrowserEngine({ spawner });

      expect(result.status).toBe('installed');
      expect(calls.filter((call) => call.bin === 'npm' && call.args[0] === 'install')).toHaveLength(1);
    });

    it.each([0, 1])('explicitly provisions missing payload and verifies it (exit %s)', (exitCode) => {
      let provisioned = false;
      const { spawner, calls } = makeSpawner((call) => {
        if (call.bin === 'npm') return canned({ stdout: 'ok' });
        if (call.args[0] === '--version') return canned({ stdout: '26.8.21' });
        if (call.args[0] === 'is-installed') return canned({ status: provisioned ? 0 : 1 });
        if (call.args[0] === 'install') {
          provisioned = exitCode === 0;
          return canned({ status: exitCode, stderr: exitCode ? 'download failed' : '' });
        }
        throw new Error('unexpected command');
      });
      const result = installBrowserEngine({ spawner });
      expect(result.status).toBe(exitCode === 0 ? 'installed' : 'install-failed');
      expect(calls).toContainEqual({ bin: 'vibium', args: ['install'] });
      if (exitCode === 1) expect(result.message).toContain('download failed');
      else expect(calls.at(-1)).toEqual({ bin: 'vibium', args: ['is-installed'] });
    });

    it('should_reportInstallFailed_when_npmSucceedsButCliVerificationFails', () => {
      const { spawner } = makeSpawner((call) => {
        if (call.bin === 'vibium') return enoent();
        if (call.bin === 'npm' && call.args[0] === '--version') return canned({ stdout: '10.2.0' });
        if (call.bin === 'npm' && call.args[0] === 'install') return canned({ stdout: 'added 1 package' });
        throw new Error(`unexpected call: ${call.bin} ${call.args.join(' ')}`);
      });

      const result = installBrowserEngine({ spawner });

      expect(result.status).toBe('install-failed');
      expect(result.version).toBeUndefined();
      expect(result.message).toMatch(/npm install -g vibium/i);
    });

    it('returns install-failed when npm install exits non-zero', () => {
      const { spawner } = makeSpawner((call) => {
        if (call.bin === 'vibium') return enoent();
        if (call.bin === 'npm' && call.args[0] === '--version') {
          return canned({ stdout: '10.2.0' });
        }
        return canned({ status: 1, stderr: 'EACCES: permission denied' });
      });
      const result = installBrowserEngine({ spawner });
      expect(result.status).toBe('install-failed');
      expect(result.message).toContain('EACCES');
    });

    it('respects a custom packageSpec', () => {
      const { spawner, calls } = makeSpawner(() => canned({ stdout: 'v26.8.21' }));
      const result = installBrowserEngine({ spawner, packageSpec: 'vibium@26.8.21' });
      expect(result.packageSpec).toBe('vibium@26.8.21');
      // Already-installed detection path should not trigger npm install.
      expect(calls).toHaveLength(2);
      expect(calls.every((call) => call.bin === 'vibium')).toBe(true);
    });

    describe('Linux ARM64 platform hint (GAP-05)', () => {
      it('attaches no platformHint on macOS (Chrome auto-download works)', () => {
        const { spawner } = makeSpawner(() => canned({ stdout: 'v26.8.21' }));
        const probe = makePlatformProbe({ platform: () => 'darwin', arch: () => 'arm64' });
        const result = installBrowserEngine({ spawner, platformProbe: probe });
        expect(result.platformHint).toBeUndefined();
      });

      it('attaches no platformHint on Linux x86_64', () => {
        const { spawner } = makeSpawner(() => canned({ stdout: 'v26.8.21' }));
        const probe = makePlatformProbe({ platform: () => 'linux', arch: () => 'x64' });
        const result = installBrowserEngine({ spawner, platformProbe: probe });
        expect(result.platformHint).toBeUndefined();
      });

      it('points Linux ARM64 at /usr/bin/chromium when present', () => {
        const { spawner } = makeSpawner(() => canned({ stdout: 'v26.8.21' }));
        const probe = makePlatformProbe({
          platform: () => 'linux',
          arch: () => 'arm64',
          existsSync: (p) => p === '/usr/bin/chromium',
        });
        const result = installBrowserEngine({ spawner, platformProbe: probe });
        expect(result.platformHint?.code).toBe('linux-arm64-system-chromium-found');
        expect(result.platformHint?.browserPath).toBe('/usr/bin/chromium');
        expect(result.platformHint?.message).toMatch(/VIBIUM_BROWSER_PATH=\/usr\/bin\/chromium/);
      });

      it('prefers /usr/bin/chromium over /usr/bin/google-chrome when both exist', () => {
        // Priority order matters — chromium is the FOSS distro default,
        // google-chrome is proprietary. Users who have both usually prefer
        // chromium, and either works with Vibium.
        const probe = makePlatformProbe({
          platform: () => 'linux',
          arch: () => 'arm64',
          existsSync: () => true, // all candidate paths present
        });
        const hint = diagnosePlatform(probe);
        expect(hint?.browserPath).toBe('/usr/bin/chromium');
      });

      it('emits the no-chromium hint when no system browser is found', () => {
        const { spawner } = makeSpawner(() => canned({ stdout: 'v26.8.21' }));
        const probe = makePlatformProbe({
          platform: () => 'linux',
          arch: () => 'arm64',
          existsSync: () => false,
        });
        const result = installBrowserEngine({ spawner, platformProbe: probe });
        expect(result.platformHint?.code).toBe('linux-arm64-no-system-chromium');
        expect(result.platformHint?.browserPath).toBeUndefined();
        expect(result.platformHint?.message).toMatch(/apt-get install chromium/);
      });
    });

    it('uses a custom npm binary when provided', () => {
      let vibiumChecks = 0;
      const { spawner, calls } = makeSpawner((call) => {
        if (call.bin === 'vibium') {
          vibiumChecks += 1;
          return vibiumChecks === 1 ? enoent() : canned({ stdout: 'v26.8.21' });
        }
        return canned({ stdout: 'ok' });
      });

      const result = installBrowserEngine({ spawner, npmBin: '/usr/local/bin/npm' });
      expect(result.status).toBe('installed');
      const npmCalls = calls.filter((c) => c.bin === '/usr/local/bin/npm');
      expect(npmCalls).toHaveLength(2);
    });
  });
});

/**
 * Task hook CLI - agent extraction tests (Issue #460)
 *
 * Regression coverage for the PostToolUse stdin path. `$TOOL_INPUT_subagent_type`
 * env-var substitution is not reliable on every hook surface (same class of
 * problem #453's file-path fallback and the UserPromptSubmit prompt fallback
 * exist to work around). Before this fix, post-task's `agent` collapsed to
 * 'unknown' whenever the env var resolved empty, so every rl_q_values row
 * landed in the same state-action bucket and the router could never learn
 * per-agent differentiation.
 */

import { describe, it, expect } from 'vitest';
import { extractAgentFromEvent } from '../../../../src/cli/commands/hooks-handlers/hooks-shared.js';

describe('extractAgentFromEvent', () => {
  it('returns empty string for empty input', () => {
    expect(extractAgentFromEvent('')).toBe('');
    expect(extractAgentFromEvent('   ')).toBe('');
  });

  it('reads tool_input.subagent_type for PostToolUse Task events (snake_case)', () => {
    const event = JSON.stringify({
      hook_event_name: 'PostToolUse',
      tool_name: 'Task',
      tool_input: { subagent_type: 'qe-test-architect' },
    });
    expect(extractAgentFromEvent(event)).toBe('qe-test-architect');
  });

  it('reads toolInput.subagentType for Task tool events (camelCase)', () => {
    const event = JSON.stringify({
      toolInput: { subagentType: 'qe-coverage-specialist' },
    });
    expect(extractAgentFromEvent(event)).toBe('qe-coverage-specialist');
  });

  it('falls back to a top-level subagent_type field', () => {
    const event = JSON.stringify({ subagent_type: 'qe-security-auditor' });
    expect(extractAgentFromEvent(event)).toBe('qe-security-auditor');
  });

  it('returns empty string when no recognized field is present', () => {
    const event = JSON.stringify({ unrelated: 'data', count: 5 });
    expect(extractAgentFromEvent(event)).toBe('');
  });

  it('ignores empty or whitespace-only subagent_type fields and tries the next candidate', () => {
    const event = JSON.stringify({
      tool_input: { subagent_type: '' },
      subagentType: '   ',
      subagent_type: 'qe-flaky-hunter',
    });
    expect(extractAgentFromEvent(event)).toBe('qe-flaky-hunter');
  });

  it('does not crash on malformed JSON — returns empty string', () => {
    expect(extractAgentFromEvent('{not valid json')).toBe('');
  });
});

/**
 * Browser Integration - Security Scanner Integration Tests
 *
 * Tests the full security audit workflow with visual-accessibility domain:
 * - URL validation → screenshot → PII scan pipeline
 * - Error propagation through pipeline
 * - Integration with security scanner and accessibility services
 *
 * These tests use mocked browser sessions since actual browser automation
 * requires Playwright/agent-browser setup.
 */

import { describe, it, expect, beforeEach, afterEach, vi } from 'vitest';
import type { IBrowserClient, IAgentBrowserClient, BrowserResult, ScreenshotResult } from '../../../src/integrations/browser/types';
import type { MemoryBackend } from '../../../src/kernel/interfaces';
import type { SecurityScannerConfig, ISecurityScannerService, DependencyScanResult } from '../../../src/domains/security-compliance/services/security-scanner';
import type { ViewportCaptureConfig, IViewportCaptureService, ViewportCaptureResult, MultiViewportCaptureResult } from '../../../src/domains/visual-accessibility/services/viewport-capture';
